ON (d.tipo = s.tipo AND d.error = s.error)
WHEN NOT MATCHED THEN INSERT (tipo, error, correcto, nivel, origen, nota)
    VALUES (s.tipo, s.error, s.correcto, s.nivel, s.origen, s.nota);

