WHEN NOT MATCHED THEN INSERT (tipo, error, correcto, nivel, origen, nota)
    VALUES (s.tipo, s.error, s.correcto, s.nivel, s.origen, s.nota);

MERGE INTO posibles_errores d
USING (
    SELECT 'categoria' AS tipo, 'correzss y bandas' AS error, 'Correas y Bandas' AS correcto, 3 AS nivel, 'auto' AS origen, 'dos errores de tipeo' AS nota FROM dual
    UNION ALL SELECT 'categoria', 'correzw y bandas', 'Correas y Bandas', 3, 'auto', 'dos errores de tipeo' FROM dual
