) s
ON (d.tipo = s.tipo AND d.error = s.error)
WHEN NOT MATCHED THEN INSERT (tipo, error, correcto, nivel, origen, nota)
    VALUES (s.tipo, s.error, s.correcto, s.nivel, s.origen, s.nota);

MERGE INTO posibles_errores d
USING (
    SELECT 'categoria' AS tipo, 'encebfido' AS error, 'Encendido' AS correcto, 3 AS nivel, 'auto' AS origen, 'dos errores de tipeo' AS nota FROM dual
    UNION ALL SELECT 'categoria', 'encebiddo', 'Encendido', 3, 'auto', 'dos errores de tipeo' FROM dual
    UNION ALL SELECT 'categoria', 'encebido', 'Encendido', 3, 'auto', 'dos errores de tipeo' FROM dual
