ON (d.tipo = s.tipo AND d.error = s.error)
WHEN NOT MATCHED THEN INSERT (tipo, error, correcto, nivel, origen, nota)
    VALUES (s.tipo, s.error, s.correcto, s.nivel, s.origen, s.nota);

MERGE INTO posibles_errores d
USING (
    SELECT 'categoria' AS tipo, 'fr1enos' AS error, 'Frenos' AS correcto, 1 AS nivel, 'auto' AS origen, 'letra de más' AS nota FROM dual
    UNION ALL SELECT 'categoria', 'fr1nos', 'Frenos', 1, 'auto', 'letra cambiada' FROM dual
    UNION ALL SELECT 'categoria', 'fr2enos', 'Frenos', 1, 'auto', 'letra de más' FROM dual
