    VALUES (s.tipo, s.error, s.correcto, s.nivel, s.origen, s.nota);

MERGE INTO posibles_errores d
USING (
    SELECT 'modelo' AS tipo, 'halux' AS error, 'Hilux' AS correcto, 1 AS nivel, 'auto' AS origen, 'letra cambiada' AS nota FROM dual
