    UNION ALL SELECT 'modelo', 'spporatge', 'Sportage', 3, 'auto', 'dos errores de tipeo' FROM dual
    UNION ALL SELECT 'modelo', 'spporfage', 'Sportage', 3, 'auto', 'dos errores de tipeo' FROM dual
